///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf07401";
scwin.SCREN_PROCS_TP_CD_01 = "01";  // 조회 — as-is 공용 상수(공급사 pcc 번들, 화면 안 선언)
scwin.SCREN_PROCS_TP_CD_03 = "03";  // 수정 — as-is 공용 상수(공급사 pcc 번들, 화면 안 선언)
scwin.SCREN_PROCS_TP_CD_08 = "08";  // PC저장 — as-is 공용 상수(공급사 pcc 번들, 화면 안 선언)
scwin.TR_JOB_INSERT = 2;  // 입력 — as-is 공용 상수(공급사 pcc 번들, 화면 안 선언)
scwin.TR_JOB_UPDATE = 3;  // 수정 — as-is 공용 상수(공급사 pcc 번들, 화면 안 선언)
scwin.TR_JOB_DELETE = 4;  // 삭제 — as-is 공용 상수(공급사 pcc 번들, 화면 안 선언)
scwin.lastJob = "";  // 업무 처리명(confirmJob 이 채우고 alertJobResult 가 읽는다 — as-is 전역 LastJob)
scwin.txa_REMK = null;
scwin.txa_INSIDE_REMK = null;
scwin.txa_EXT_OPN_VALU_RSLT_REMK = null;
scwin.btn_Update = null;
scwin.btn_Save = null;
scwin.btn_Delete = null;
scwin.btn_Acpt = null;
scwin.TR_JOB = undefined;
scwin.fileSizeLimit = 104857600;
scwin.isSuspn = false;
scwin.isReSuspn = false;
scwin.isStatusUpdate = false;
scwin.dts_info = null;
scwin.dts_fileList = null;
scwin.dts_Cod = null;
scwin.dts_BzProcsNo = null;
scwin.dts_ExecInstList = null;
scwin.dts_fileInfo = null;
scwin.dts_instCmb = null;
scwin.dts_instCmb2 = null;
