///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        scwin.setTrJob();
        await scwin.searchCode();
        scwin.fn_grdSearchCode();
        scwin.fn_setSkilValueInstCdCmb();
        scwin.fn_grdList();
        buttonSet.setSaveInfo(scwin.btn_Save, scwin.save);
        buttonSet.setUpdateInfo(scwin.btn_Update, scwin.update);
        buttonSet.setDeleteInfo(scwin.btn_Delete, scwin.delete);
        if (scwin.TR_JOB !== "I") {
            scwin.fn_commList();
            scwin.fn_fileList();
            buttonSet.setUpdateStatus();
        } else {
            scwin.dts_info.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=SPECY_VALU_INOUT";
            scwin.dts_info.reset();
            (scwin.dts_info.insertRow(), scwin.dts_info.setRowPosition(scwin.dts_info.getRowCount()-1));
            rd_rdo_SKIL_BZ_TP_CD.setValue("01");
            rd_rdo_VALU_INST_APPL_CNT.setValue("2");
            scwin.dts_fileInfo.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=KSQ_SKIL_VALU_FILE_INOUT";
            scwin.dts_fileInfo.reset();
            buttonSet.setInsertStatus();
        }
        await scwin.setCmbTxt();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07401.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.fileTpCdarr =["011", "021", "022", "023", "031", "041", "051", "061", "062", "063", "", "071", "081", "091", "101", "102", "103","111","121","131","132","133","141"]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf07401' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.txa_REMK = $c.util.getComponent('txa_REMK');
        scwin.txa_INSIDE_REMK = $c.util.getComponent('txa_INSIDE_REMK');
        scwin.txa_EXT_OPN_VALU_RSLT_REMK = $c.util.getComponent('txa_EXT_OPN_VALU_RSLT_REMK');
        scwin.btn_Update = $c.util.getComponent('btn_Update');
        scwin.btn_Save = $c.util.getComponent('btn_Save');
        scwin.btn_Delete = $c.util.getComponent('btn_Delete');
        scwin.btn_Acpt = $c.util.getComponent('btn_Acpt');
        scwin.dts_info = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsInfo')) : $c.util.getComponent('dtsInfo');
        scwin.dts_fileList = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsFileList')) : $c.util.getComponent('dtsFileList');
        scwin.dts_Cod = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_Cod')) : $c.util.getComponent('dts_Cod');
        scwin.dts_BzProcsNo = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_BzProcsNo')) : $c.util.getComponent('dts_BzProcsNo');
        scwin.dts_ExecInstList = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_ExecInstList')) : $c.util.getComponent('dts_ExecInstList');
        scwin.dts_fileInfo = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsFileInfo')) : $c.util.getComponent('dtsFileInfo');
        scwin.dts_instCmb = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsInstCmb')) : $c.util.getComponent('dtsInstCmb');
        scwin.dts_instCmb2 = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsInstCmb2')) : $c.util.getComponent('dtsInstCmb2');
        scwin.dts_LeadCom = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_LeadCom')) : $c.util.getComponent('dts_LeadCom');
        scwin.dts_GrdCdList = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_GrdCdList')) : $c.util.getComponent('dts_GrdCdList');
        scwin.dts_PROCS_STAT_CD = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_PROCS_STAT_CD')) : $c.util.getComponent('dts_PROCS_STAT_CD');
        scwin.upd_infFind = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_infFind') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_infFind"]');
        scwin.fn_grdSearchCode = scwin.tx_script_dts_Cod;
        scwin.fn_trs = scwin.sbm_trs_Save;
        scwin.fn_commList = scwin.tx_script_dts_info;
        scwin.fn_grdList = scwin.tx_script_dts_ExecInstList;
        scwin.fn_fileList = scwin.tx_script_dts_fileInfo;
        scwin.fn_setSkilValueInstCdCmb = scwin.tx_script_dts_instCmb;
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf07401.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
