    /* empty */
};

/**
 * @method
 * @name trs_Save_onfail
 * @description trs_Save onfail 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_onfail = async function () {
    try {
        await scwin.alertJobResult('F');
        $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldstf07401.trs_Save_onfail" });
    }
};

/**
 * @method
 * @name trs_Save_onsuccess
 * @description trs_Save onsuccess 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_onsuccess = async function () {
    try {
        // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CloseFrame
        if (scwin.isStatusUpdate) {
            await scwin.alertJobResult('S1');
        } else {
            await scwin.alertJobResult('S');
        }
        scwin.parentRefresh();
        if (scwin.TR_JOB === "D") {
            $c.win.closePopup();
        } else {
            scwin.fn_commList();
            scwin.fn_fileList();
            buttonSet.setUpdateStatus();
            await scwin.setCmbTxt();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldstf07401.trs_Save_onsuccess" });
    }
};

