/**
 * @method
 * @name cmb_SKIL_VALU_INST_CD2_onselchange
 * @description cmb_SKIL_VALU_INST_CD2 onselchange 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_SKIL_VALU_INST_CD2_onselchange = async function () {
    try {
        const skilValuInstCd2 = slc_cmb_SKIL_VALU_INST_CD2.getValue();
        const skilValuInstCd1 = slc_cmb_SKIL_VALU_INST_CD1.getValue();
        if (skilValuInstCd1 !== "" && skilValuInstCd2 === skilValuInstCd1) {
            await $c.win.alert("평가기관1과 동일한값입니다");
            slc_cmb_SKIL_VALU_INST_CD2.setValue("");
            $c.util.getComponent("slc_cmb_SKIL_VALU_INST_CD2").focus();
            return;
        }
        const skilValuInstText2 = slc_cmb_SKIL_VALU_INST_CD2.valueOfIndex("TEXT", slc_cmb_SKIL_VALU_INST_CD2.Index);
        if (skilValuInstText2.indexOf("제척") > -1) {
            await $c.win.alert("평가기관에 제척기관은 선택할 수 없습니다");
            slc_cmb_SKIL_VALU_INST_CD2.setValue("");
            $c.util.getComponent("slc_cmb_SKIL_VALU_INST_CD2").focus();
            return;
        }
        scwin.valuInstCd2();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07401.cmb_SKIL_VALU_INST_CD2_onselchange' }); }
};

/**
 * @method
 * @name cmb_SKIL_VALU_INST_CD1_onselchange
 * @description cmb_SKIL_VALU_INST_CD1 onselchange 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_SKIL_VALU_INST_CD1_onselchange = async function () {
    try {
        const skilValuInstCd2 = slc_cmb_SKIL_VALU_INST_CD2.getValue();
        const skilValuInstCd1 = slc_cmb_SKIL_VALU_INST_CD1.getValue();
        if (skilValuInstCd2 !== "" && skilValuInstCd2 === skilValuInstCd1) {
            await $c.win.alert("평가기관2와 동일한값입니다");
            slc_cmb_SKIL_VALU_INST_CD1.setValue("");
            $c.util.getComponent("slc_cmb_SKIL_VALU_INST_CD1").focus();
            return;
        }
        const skilValuInstText1 = slc_cmb_SKIL_VALU_INST_CD1.valueOfIndex("TEXT", slc_cmb_SKIL_VALU_INST_CD1.Index);
        if (skilValuInstText1.indexOf("제척") > -1) {
            await $c.win.alert("평가기관에 제척기관은 선택할 수 없습니다");
            slc_cmb_SKIL_VALU_INST_CD1.setValue("");
            $c.util.getComponent("slc_cmb_SKIL_VALU_INST_CD1").focus();
            return;
        }
        scwin.valuInstCd1();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07401.cmb_SKIL_VALU_INST_CD1_onselchange' }); }
};

