/**
 * @method
 * @name searchCode
 * @description search Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCode = async function () {
    const arrCid = [{ cid: "ONECOM_APPL_RSN_CD", cnm: "cmb_ONECOM_APPL_RSN_CD" }, { cid: "SKIL_VALU_PROG_STAT_CD", cnm: "cmb_SKIL_VALU_PROG_STAT_CD" }, { cid: "SKIL_VALU_GRD_CD", cnm: "cmb_SKIL_VALU_GRD_CD1" }, { cid: "SKIL_VALU_GRD_CD", cnm: "cmb_SKIL_VALU_GRD_CD2" }, { cid: "SPECY_VALU_IND_CLSS_CD", cnm: "cmb_SPECY_VALU_IND_CLSS_CD" }, { cid: "SPECY_VALU_IND_CLSS_CD", cnm: "cmb_SPECY_VALU_IND_CLSS_CD2" }, { cid: "SPECY_VALU_SKIL_CLSS_CD", cnm: "cmb_SPECY_VALU_SKIL_CLSS_CD" }, { cid: "SPECY_VALU_SKIL_CLSS_CD", cnm: "cmb_SPECY_VALU_SKIL_CLSS_CD2" }];
    let objCod;
    const url = "/CodeAction.do?SCREN_ID=" + "ULDSTF07041.gfm" + "&SCREN_PROCES_TP_CD=" + scwin.SCREN_PROCS_TP_CD_01 + "&method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='ONECOM_APPL_RSN_CD','SKIL_VALU_PROG_STAT_CD','SPECY_VALU_INST_CD','SKIL_VALU_GRD_CD', 'SPECY_VALU_IND_CLSS_CD', 'SPECY_VALU_SKIL_CLSS_CD'";

    await scwin.tx_script_dts_Cod();
    let strCbd = "", i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = $c.util.getComponent(arrCid[i].cnm);
        if (objCod == null) {
            await $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "^ ";
        if (i === 0) {
            strCbd = "^직접입력";
        }
        for (j = 1; j <= scwin.dts_Cod.CountRow; j++) {
            if (scwin.dts_Cod.getCellData(j, "CD_ENG_NM") === arrCid[i].cid) {
                const cmbValue = scwin.dts_Cod.getCellData(j, "VALUE");
                const cmbText = scwin.dts_Cod.getCellData(j, "TEXT");
                strCbd = strCbd + (strCbd === "" ? "" : ",") + cmbValue + "^" + cmbText;
            }
        }
        if(objCod)objCod.CBData=strCbd;
    }
};

