/**
 * @method
 * @name checkGrid
 * @description check Grid 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkGrid = async function () {
    let comCd, compCdIn;
    for (let i = 1, j = scwin.dts_LeadCom.CountRow; i <= j; i++) {
        comCd = scwin.dts_LeadCom.getCellData(i, "LEADCOM_MBR_NO");
        if (comCd === "") {
            await $c.win.alert("주관사에 빈값을 선택할수 없스니다.");
            return false;
        }
        for (let k = 1, l = scwin.dts_LeadCom.CountRow; k <= l; k++) {
            if (i === k) {
                continue;
            }
            compCdIn = scwin.dts_LeadCom.getCellData(k, "LEADCOM_MBR_NO");
            if (comCd === compCdIn) {
                await $c.win.alert("동일한 주관사는 입력할 수 없습니다.");
                return false;
            }
        }
    }
    for (let i = 1, j = scwin.dts_ExecInstList.CountRow; i <= j; i++) {
        comCd = scwin.dts_ExecInstList.getCellData(i, "SPECY_VALU_INST_CD");
        if (comCd === "") {
            await $c.win.alert("제척기관에 빈값을 선택할수 없스니다.");
            return false;
        }
        for (let k = 1, l = scwin.dts_ExecInstList.CountRow; k <= l; k++) {
            if (i === k) {
                continue;
            }
            compCdIn = scwin.dts_ExecInstList.getCellData(k, "SPECY_VALU_INST_CD");
            if (comCd === compCdIn) {
                await $c.win.alert("동일한 제척기관은 입력할 수 없습니다.");
                return false;
            }
        }
    }
    return true;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.fil.fn_getNewBzProcNo
    scwin.TR_JOB = 'I';
    if (await scwin.checkForm() && await scwin.checkGrid() && await scwin.fncheckInstCheck()) {
        if (!await scwin.confirmJob(scwin.TR_JOB)) {
            return;
        }
        vBzProcsNo = $c.fil.fn_getNewBzProcNo(scwin.dts_BzProcsNo);
        if (vBzProcsNo.length !== 14) {
            await $c.win.alert($c.data.getMessage("MSG-0010", ""));
        } else {
            scwin.dts_info.setCellData(1, "BZ_PROCS_NO", vBzProcsNo);
            scwin.fn_trs(scwin.TR_JOB_INSERT);
        }
    }
};

/**
 * @method
 * @name changeApplCnt
 * @description change Appl Cnt 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.changeApplCnt = async function () {
    const applCnt = rd_rdo_VALU_INST_APPL_CNT.getValue();
    const valueYn = slc_cmb_ONECOM_APPL_RSN_CD.getValue();
    if (valueYn === "99" && applCnt === "1") {
        await $c.win.alert("특례대상여부가 해당없음인 경우 1사 선택 불가");
        rd_rdo_VALU_INST_APPL_CNT.setValue("2");
        rd_rdo_VALU_INST_APPL_CNT.removeAll();
        return;
    }
    if (applCnt === "1") {
