/**
 * @method
 * @name fileClick
 * @description file Click 처리
 * @param {*} fileDiv fileDiv
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileClick = async function (fileDiv) {
    if (scwin.upd_infFind.Value === "") {
        return;
    }
    const fileFullPath = scwin.upd_infFind.Value;
    const temp = (fileFullPath).split("\\");
    const fileName = temp[temp.length - 1];
    if (await scwin.checkFileNameSize(fileName)) {
        return false;
    }
    const txbFileOb = $p.getComponentById("txb_FILE_NM" + fileDiv);
    txbFileOb.value = scwin.upd_infFind.Value;
    const fileRow = scwin.dts_fileInfo.NameValueRow("FILE_DIV", scwin.fileTpCdarr[fileDiv - 1]);
    if (fileRow > 0) {
        scwin.dts_fileInfo.setCellData(fileRow, "fileInfo", fileFullPath);
        scwin.dts_fileInfo.setCellData(fileRow, "fileUrl", fileFullPath);
        scwin.dts_fileInfo.setCellData(fileRow, "ATTACH_FILE_SZ", scwin.upd_infFind.FileInfo("size"));
        scwin.dts_fileInfo.setCellData(scwin.dts_fileInfo.CountRow, "FILE_DIV", scwin.fileTpCdarr[fileDiv - 1].substring(0, 2) + scwin.fileTpCdarr[fileDiv - 1].substring(2, 3));
    } else {
        (scwin.dts_fileInfo.insertRow(), scwin.dts_fileInfo.setRowPosition(scwin.dts_fileInfo.getRowCount()-1));
        scwin.dts_fileInfo.setCellData(scwin.dts_fileInfo.CountRow, "fileInfo", fileFullPath);
        scwin.dts_fileInfo.setCellData(scwin.dts_fileInfo.CountRow, "fileUrl", fileFullPath);
        scwin.dts_fileInfo.setCellData(scwin.dts_fileInfo.CountRow, "ATTACH_FILE_SZ", scwin.upd_infFind.FileInfo("size"));
        scwin.dts_fileInfo.setCellData(scwin.dts_fileInfo.CountRow, "SEQ", scwin.fileTpCdarr[fileDiv - 1].substring(2, 3));
        scwin.dts_fileInfo.setCellData(scwin.dts_fileInfo.CountRow, "SKIL_VALU_ATTACH_FILE_TP_CD", scwin.fileTpCdarr[fileDiv - 1].substring(0, 2));
        scwin.dts_fileInfo.setCellData(scwin.dts_fileInfo.CountRow, "BZ_PROCS_NO", vBzProcsNo);
        scwin.dts_fileInfo.setCellData(scwin.dts_fileInfo.CountRow, "FILE_DIV", scwin.fileTpCdarr[fileDiv - 1].substring(0, 2) + scwin.fileTpCdarr[fileDiv - 1].substring(2, 3));
        const deleteIcon = $p.getComponentById("file_delete" + fileDiv);
        scwin.showObj(deleteIcon, true);
    }
    scwin.upd_infFind.Value = "";
};

/**
 * @method
 * @name checkFileNameSize
 * @description check File Name Size 처리
 * @param {*} fileName fileName
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkFileNameSize = async function (fileName) {
    const nameByte = $c.str.getByteLength(fileName);
    const overLen = (nameByte - 80);
    let isValid = false;
    if (overLen > 0) {
        await $c.win.alert("파일명의 최대길이는 80byte입니다. 파일명 길이를 확인하세요 (한글 : 2 byte 숫자,영문 : 1byte)");
        isValid = true;
    }
    return isValid;
};

/**
 * @method
 * @name fncheckInstCheck
 * @description fncheck Inst Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fncheckInstCheck = async function () {
    const instCd1 = slc_cmb_SKIL_VALU_INST_CD1.getValue();
    const instCd2 = slc_cmb_SKIL_VALU_INST_CD2.getValue();
    let execInstCd;
    for (let i = 1, j = scwin.dts_ExecInstList.CountRow; i <= j; i++) {
        execInstCd = scwin.dts_ExecInstList.getCellData(i, "SPECY_VALU_INST_CD");
        if (execInstCd !== "") {
            if (execInstCd === instCd1 || execInstCd === instCd2) {
                await $c.win.alert("제척기관은 평가기관으로 선택할수 없습니다.");
                return false;
            }
        }
    }
    return true;
};

/**
 * @method
 * @name setFileInfo
 * @description set File Info 처리
 * @returns {void}
 * @hidden N
 */
scwin.setFileInfo = function () {
    let txbFileObj, findRow, fileTpCd, lastName, isTrue;
    const fileDownIcon = "down_file";
    const fileDelIcon = "file_delete";
    for (let i = 1; i <= 23; i++) {
        if (i === 11) {
            continue;
        }
        txbFileObj = $p.getComponentById("txb_FILE_NM" + i);
        findRow = scwin.dts_fileInfo.NameValueRow("FILE_DIV", scwin.fileTpCdarr[i - 1]);
        const downIcon = (fileDownIcon + i);
        const deleteIcon = (fileDelIcon + i);
        if (findRow > 0) {
            txbFileObj.value = scwin.dts_fileInfo.getCellData(findRow, "ATTACH_FILE_NM");
            isTrue = true;
        } else {
            txbFileObj.value = "";
            isTrue = false;
        }
        scwin.showObj(downIcon, isTrue);
        scwin.showObj(deleteIcon, isTrue);
    }
};

/**
 * @method
 * @name fileDelete
 * @description file Delete 처리
 * @param {*} fileDiv fileDiv
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileDelete = async function (fileDiv) {
    let txtFileObj, fileRow;
    txtFileObj = $p.getComponentById("txb_FILE_NM" + fileDiv);
    if (txtFileObj.value === "") {
        return;
    } else {
        if (await $c.win.confirm("파일을 삭제하시겠습니까?")) {
            txtFileObj.value = "";
            fileRow = scwin.dts_fileInfo.NameValueRow("FILE_DIV", scwin.fileTpCdarr[fileDiv - 1]);
            if (fileRow > 0) {
                scwin.dts_fileInfo.removeRow(fileRow);
            }
        }
    }
};

