 */
scwin.showObj = function (obj, flag) {
    const comp = (typeof obj === "string") ? $c.util.getComponent(obj) : obj;
    if (!comp) { return; }
    if (flag) { comp.show(); } else { comp.hide(); }
};

/**
 * @method
 * @name getModalCenterPos
 * @description 모달 창을 화면 중앙에 놓을 좌표(as-is 공통 fn_getModalCenterPos)
 * @param {*} opnFrm 여는 창(window)
 * @param {*} frmWth 창 너비
 * @param {*} frmHgt 창 높이
 * @returns {Object} { x, y }
 * @hidden N
 */
scwin.getModalCenterPos = function (opnFrm, frmWth, frmHgt) {
    return { x: window.screen.width / 2 - opnFrm.screenLeft - frmWth / 2, y: window.screen.height / 2 - opnFrm.screenTop - frmHgt / 2 };
};

/**
 * @method
 * @name confirmJob
 * @description 업무 처리 확인 — "[저장] 하시겠습니까?" 확인창(as-is 공통 fn_isProcess 의 의미 보존 · pcc/fil 반입 후보)
 * @param {*} gubun 처리 구분(I 저장 · U 수정 · D 삭제 · S 제출 · R 해제 · DSCL 안내문작성)
 * @returns {Promise<Boolean>} 확인이면 true
 * @hidden N
 */
scwin.confirmJob = async function (gubun) {
    const job = { I: "저장", U: "수정", D: "삭제", S: "제출", R: "해제", DSCL: "안내문작성" }[gubun] || gubun;
    scwin.lastJob = job;  // 결과 알림(alertJobResult)이 같은 처리명을 쓴다 — as-is 전역 LastJob
    return $c.win.confirm("[" + job + "] 하시겠습니까?");
};

/**
 * @method
 * @name alertJobResult
 * @description 업무 처리 결과 알림 — S "[처리명] 처리 성공하였습니다." · S1 "성공적으로 처리되었습니다." · F "[처리명] 처리 실패하였습니다."
 * @param {*} gubun 결과 구분(S 성공 · S1 성공(처리명 없음) · F 실패)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.alertJobResult = async function (gubun) {
    const job = scwin.lastJob || "";
    if (gubun === "S") { await $c.win.alert("[" + job + "] 처리 성공하였습니다."); }
    else if (gubun === "S1") { await $c.win.alert("성공적으로 처리되었습니다."); }
    else if (gubun === "F") { await $c.win.alert("[" + job + "] 처리 실패하였습니다."); }
};
